@SpringBootTest(properties="app.answer-assets.directory=target/test-answer-assets") @AutoConfigureMockMvc
class M04IntegrationTest {
 @Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 final String prefix="m04"+UUID.randomUUID().toString().replace("-","").substring(0,10);final String password="valid-password-123";Cookie first,other;long firstUser,otherUser,chapter,kp,emptyKp;

 @BeforeEach void setup()throws Exception {var encoder=new BCryptPasswordEncoder();firstUser=user(prefix+"first",encoder);otherUser=user(prefix+"other",encoder);first=login(prefix+"first");other=login(prefix+"other");int n=100+Math.floorMod(prefix.hashCode(),800);chapter=db.queryForObject("INSERT INTO rs_chapter(subject_id,code,name,sort_order) VALUES (1,?,?,?) RETURNING id",Long.class,"M04"+n,prefix+"chapter",n);kp=knowledge("M04"+n+"-KP1",prefix+"with-questions",1);emptyKp=knowledge("M04"+n+"-KP2",prefix+"empty",2);}
 @AfterEach void clean(){db.query("SELECT storage_key FROM rs_answer_asset WHERE user_id IN (?,?)",r->{try{Files.deleteIfExists(Path.of("target/test-answer-assets",r.getString(1)));}catch(Exception ignored){}},firstUser,otherUser);db.update("DELETE FROM rs_question_feedback WHERE user_id IN (?,?)",firstUser,otherUser);db.update("UPDATE rs_wrong_question SET latest_attempt_id=NULL WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_wrong_attempt WHERE wrong_question_id IN (SELECT id FROM rs_wrong_question WHERE user_id IN (?,?))",firstUser,otherUser);db.update("DELETE FROM rs_wrong_question WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_answer_asset WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_change_event WHERE source_id IN (SELECT id FROM rs_practice WHERE user_id IN (?,?))",firstUser,otherUser);db.update("DELETE FROM rs_mastery_current WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_mastery_snapshot WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_evidence WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_student_course_guard WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_practice_item WHERE practice_id IN (SELECT id FROM rs_practice WHERE user_id IN (?,?))",firstUser,otherUser);db.update("DELETE FROM rs_practice WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_learning_activity WHERE user_id IN (?,?)",firstUser,otherUser);List<Long> questions=db.query("SELECT id FROM rs_question WHERE question_no LIKE ?",(r,n)->r.getLong(1),prefix+"%");for(long id:questions){db.update("UPDATE rs_question SET current_version_id=NULL WHERE id=?",id);db.update("DELETE FROM rs_question_version WHERE question_id=?",id);db.update("DELETE FROM rs_question WHERE id=?",id);}db.update("DELETE FROM rs_knowledge_point WHERE chapter_id=?",chapter);db.update("DELETE FROM rs_chapter WHERE id=?",chapter);db.update("DELETE FROM rs_session WHERE user_id IN (?,?)",firstUser,otherUser);db.update("DELETE FROM rs_user WHERE id IN (?,?)",firstUser,otherUser);}

 @Test void zeroQuestionKnowledgePointIsRejected()throws Exception {mvc.perform(post("/api/practices").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"empty").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("knowledgeIds",List.of(String.valueOf(emptyKp)),"questionCount",1)))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("NO_AVAILABLE_QUESTION")).andExpect(jsonPath("$.message").value(org.hamcrest.Matchers.containsString("KP2")));}

 @Test void scarceSingleKnowledgeUsesEveryQuestionOnceAndReportsRequestedCount()throws Exception {for(int i=0;i<4;i++)question("CHOICE","scarce-"+i,choiceContent("scarce-"+i),Map.of("correctOption","A"),null,2);JsonNode created=create(first,prefix+"scarce",List.of(kp),5);long practiceId=created.get("id").asLong();assertEquals(4,created.get("items").size());assertEquals(4,created.get("questionCount").asInt());assertEquals(5,created.get("requestedCount").asInt());JsonNode mix=created.get("mixRatio");int plannedBank=mix.at("/planned/bank").asInt(),plannedAi=mix.at("/planned/ai").asInt();assertEquals(5,plannedBank+plannedAi);assertEquals(plannedAi,mix.get("degraded").size());assertEquals(4,db.queryForObject("SELECT question_count FROM rs_practice WHERE id=?",Integer.class,practiceId));assertEquals(4L,db.queryForObject("SELECT count(*) FROM rs_practice_item WHERE practice_id=?",Long.class,practiceId));assertEquals(4L,db.queryForObject("SELECT count(DISTINCT question_id) FROM rs_practice_item WHERE practice_id=?",Long.class,practiceId));}

 @Test void multipleKnowledgePointsArePickedRoundRobinWithoutDuplicates()throws Exception {for(int i=0;i<3;i++){question(kp,"CHOICE","rr-a-"+i,choiceContent("rr-a-"+i),Map.of("correctOption","A"),null,2);question(emptyKp,"CHOICE","rr-b-"+i,choiceContent("rr-b-"+i),Map.of("correctOption","A"),null,2);}JsonNode created=create(first,prefix+"round-robin",List.of(kp,emptyKp),5);assertEquals(5,created.get("items").size());Set<String> questionIds=new HashSet<>();created.get("items").forEach(item->questionIds.add(item.get("questionId").asText()));assertEquals(5,questionIds.size());assertEquals(String.valueOf(kp),created.at("/items/0/knowledgeId").asText());assertEquals(String.valueOf(kp),created.at("/items/2/knowledgeId").asText());assertEquals(String.valueOf(kp),created.at("/items/4/knowledgeId").asText());assertEquals(String.valueOf(emptyKp),created.at("/items/1/knowledgeId").asText());assertEquals(String.valueOf(emptyKp),created.at("/items/3/knowledgeId").asText());}

 @Test void maximumRequestStillStopsAtAvailableQuestions()throws Exception {for(int i=0;i<4;i++)question("CHOICE","max-"+i,choiceContent("max-"+i),Map.of("correctOption","A"),null,2);JsonNode created=create(first,prefix+"maximum",List.of(kp),20);assertEquals(4,created.get("items").size());assertEquals(4,created.get("questionCount").asInt());assertEquals(20,created.get("requestedCount").asInt());}

 @Test void requestBelowCapacityKeepsOriginalQuestionOrder()throws Exception {List<Long> expected=new ArrayList<>();for(int i=0;i<5;i++)expected.add(question("CHOICE","order-"+i,choiceContent("order-"+i),Map.of("correctOption","A"),null,2));JsonNode created=create(first,prefix+"order",List.of(kp),3);assertEquals(3,created.get("items").size());assertEquals(3,created.get("questionCount").asInt());assertEquals(3,created.get("requestedCount").asInt());for(int i=0;i<3;i++)assertEquals(String.valueOf(expected.get(i)),created.at("/items/"+i+"/questionId").asText());}

 @Test void activeActivityConflictIncludesExistingIdentity()throws Exception {question("CHOICE","active",choiceContent("active"),Map.of("correctOption","A"),null,2);JsonNode made=create(first,prefix+"active1",List.of(kp),1);mvc.perform(post("/api/practices").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"active2").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("knowledgeIds",List.of(String.valueOf(kp)),"questionCount",1)))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("STATE_CONFLICT")).andExpect(jsonPath("$.activityId").value(made.get("activityId").asText())).andExpect(jsonPath("$.kind").value("PRACTICE"));}

 @Test void draftUsesOptimisticLockAndSourceModeIsRejected()throws Exception {question("CHOICE","draft",choiceContent("draft"),Map.of("correctOption","A"),null,2);JsonNode made=create(first,prefix+"draft",List.of(kp),1);long id=made.get("id").asLong(),item=made.at("/items/0/id").asLong();start(first,id);mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"draftVersion\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"answer\":null,\"draftVersion\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"answer\":{},\"draftVersion\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));String body=json.writeValueAsString(Map.of("answer",Map.of("selectedOption","A"),"draftVersion",0));mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.draftVersion").value(1));mvc.perform(get("/api/practices/"+id).cookie(first)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].draft.selectedOption").value("A"));mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("STATE_CONFLICT"));mvc.perform(get("/api/practices/"+id).param("sourceMode","MANUAL").cookie(first)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));}

 @Test void gradingSubmissionAndResultVisibilityFollowBoundaries()throws Exception {question("CHOICE","choice-ok",choiceContent("choice-ok"),Map.of("correctOption","A"),null,2);question("CHOICE","choice-empty",choiceContent("choice-empty"),Map.of("correctOption","A"),null,2);question("FILL","fill-ok",Map.of("stem","First {{blank}}, second {{blank}}","explanation","fill explanation"),Map.of("blanks",List.of(Map.of("accepted",List.of("Stack")),Map.of("accepted",List.of("队列")))),null,2);question("FILL","fill-partial",Map.of("stem","First {{blank}}, second {{blank}}","explanation","partial explanation"),Map.of("blanks",List.of(Map.of("accepted",List.of("Ａ")),Map.of("accepted",List.of("B")))),null,2);question("SHORT_ANSWER","short",Map.of("stem","Explain","explanation","short explanation"),Map.of("referenceAnswer","reference"),rubric(10),10);question("ALGORITHM","algorithm",Map.of("stem","Design","explanation","algorithm explanation"),Map.of("referenceAnswer","reference"),rubric(10),10);JsonNode made=create(first,prefix+"grade",List.of(kp),6);long id=made.get("id").asLong();start(first,id);String before=mvc.perform(get("/api/practices/"+id).cookie(first)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertNoSecrets(json.readTree(before));mvc.perform(get("/api/practices/"+id).cookie(other)).andExpect(status().isNotFound());List<Map<String,Object>> answers=new ArrayList<>();for(JsonNode item:made.get("items")){String type=item.get("type").asText(),stem=item.at("/content/stem").asText();Object answer=switch(type){case "CHOICE"->stem.contains("empty")?Map.of("selectedOption",""):Map.of("selectedOption","A");case "FILL"->stem.startsWith("First")&&answers.stream().noneMatch(a->((Map<?,?>)a.get("answer")).containsKey("blanks"))?Map.of("blanks",List.of(" ＳＴＡＣＫ ","队列")):Map.of("blanks",List.of("A","wrong"));default->Map.of("text","response","code",type.equals("ALGORITHM")?"return 1;":"");};answers.add(Map.of("itemId",item.get("id").asText(),"answer",answer,"assetIds",List.of()));}String submit=json.writeValueAsString(Map.of("answers",answers));MvcResult submitted=mvc.perform(post("/api/practices/"+id+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"submit").contentType(MediaType.APPLICATION_JSON).content(submit)).andExpect(status().isOk()).andReturn();JsonNode result=json.readTree(submitted.getResponse().getContentAsString());assertEquals(6,result.get("items").size());assertEquals(2,countResult(result,"AUTO_GRADED","passed",true));assertEquals(2,countResult(result,"AUTO_GRADED","passed",false));assertEquals(2,countStatus(result,"AI_REVIEW_PENDING"));for(JsonNode item:result.get("items"))if(item.get("type").asText().equals("FILL")&&item.at("/result/blank_results/0/correct").asBoolean()&&!item.at("/result/passed").asBoolean())assertEquals(0,item.at("/result/normalized_score").asInt());assertTrue(result.toString().contains("correctAnswer"));mvc.perform(post("/api/practices/"+id+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"submit").contentType(MediaType.APPLICATION_JSON).content(submit)).andExpect(status().isOk()).andExpect(content().json(submitted.getResponse().getContentAsString()));mvc.perform(post("/api/practices/"+id+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"submit").contentType(MediaType.APPLICATION_JSON).content("{\"answers\":[]}" )).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("IDEMPOTENCY_CONFLICT"));mvc.perform(get("/api/practices/"+id+"/result").cookie(first)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].correctAnswer").exists());}

 @Test void answerImagesEnforceFormatCountOwnershipAndSubmissionFreeze()throws Exception {question("SHORT_ANSWER","image",Map.of("stem","Explain with image","explanation","answer"),Map.of("referenceAnswer","reference"),rubric(10),10);JsonNode made=create(first,prefix+"image",List.of(kp),1);long id=made.get("id").asLong(),item=made.at("/items/0/id").asLong();start(first,id);var fake=new MockMultipartFile("file","fake.png","image/png","not image".getBytes());mvc.perform(multipart("/api/practices/"+id+"/items/"+item+"/assets").file(fake).cookie(first).with(csrf())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("UPLOAD_INVALID"));long asset=0;for(int i=0;i<3;i++){var file=new MockMultipartFile("file","p"+i+".png","image/png",png());JsonNode uploaded=json.readTree(mvc.perform(multipart("/api/practices/"+id+"/items/"+item+"/assets").file(file).cookie(first).with(csrf())).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());asset=uploaded.get("id").asLong();}mvc.perform(multipart("/api/practices/"+id+"/items/"+item+"/assets").file(new MockMultipartFile("file","four.png","image/png",png())).cookie(first).with(csrf())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("UPLOAD_INVALID"));mvc.perform(get("/api/practice-assets/"+asset).cookie(other)).andExpect(status().isNotFound());String submit=json.writeValueAsString(Map.of("answers",List.of(Map.of("itemId",String.valueOf(item),"answer",Map.of("text","answer"),"assetIds",List.of(String.valueOf(asset))))));mvc.perform(post("/api/practices/"+id+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"image-submit").contentType(MediaType.APPLICATION_JSON).content(submit)).andExpect(status().isOk());mvc.perform(put("/api/practices/"+id+"/items/"+item+"/draft").cookie(first).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"answer\":{},\"draftVersion\":0}" )).andExpect(status().isConflict());}

 @Test void cancelOnlyWorksBeforeStartAndHistoryIsPaged()throws Exception {question("CHOICE","cancel",choiceContent("cancel"),Map.of("correctOption","A"),null,2);JsonNode made=create(first,prefix+"cancel",List.of(kp),1);long id=made.get("id").asLong();mvc.perform(post("/api/practices/"+id+"/cancel").cookie(first).with(csrf())).andExpect(status().isNoContent());JsonNode next=create(first,prefix+"history",List.of(kp),1);long nextId=next.get("id").asLong();start(first,nextId);String submit=json.writeValueAsString(Map.of("answers",List.of(Map.of("itemId",next.at("/items/0/id").asText(),"answer",Map.of("selectedOption","A"),"assetIds",List.of()))));mvc.perform(post("/api/practices/"+nextId+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"history-submit").contentType(MediaType.APPLICATION_JSON).content(submit)).andExpect(status().isOk());mvc.perform(get("/api/practices/history").param("page","0").param("size","1000").cookie(first)).andExpect(status().isOk()).andExpect(jsonPath("$.size").value(100)).andExpect(jsonPath("$.total").value(1));}

 @Test void unknownAnswerItemRejectsSubmissionAtomically()throws Exception {question("CHOICE","unknown",choiceContent("unknown"),Map.of("correctOption","A"),null,2);JsonNode made=create(first,prefix+"unknown",List.of(kp),1);long id=made.get("id").asLong();start(first,id);String body=json.writeValueAsString(Map.of("answers",List.of(Map.of("itemId",made.at("/items/0/id").asText(),"answer",Map.of("selectedOption","A")),Map.of("itemId","999999999999","answer",Map.of("selectedOption","A")))));mvc.perform(post("/api/practices/"+id+"/submit").cookie(first).with(csrf()).header("Idempotency-Key",prefix+"unknown-submit").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED")).andExpect(jsonPath("$.message").value("Answer item does not belong to the practice"));assertEquals("IN_PROGRESS",db.queryForObject("SELECT a.status FROM rs_practice p JOIN rs_learning_activity a ON a.id=p.activity_id WHERE p.id=?",String.class,id));assertEquals(0L,db.queryForObject("SELECT count(*) FROM rs_practice_item WHERE practice_id=? AND result_json IS NOT NULL",Long.class,id));}
 @Test void repeatedSubmitKeepsGradingAndResultUnchanged()throws Exception {question("CHOICE","repeat-submit",choiceContent("repeat-submit"),Map.of("correctOption","A"),null,2);JsonNode made=create(first,prefix+"repeat-submit",List.of(kp),1);long id=made.get("id").asLong(),item=made.at("/items/0/id").asLong();start(first,id);String body=json.writeValueAsString(Map.of("answers",List.of(Map.of("itemId",String.valueOf(item),"answer",Map.of("selectedOption","A")))));String path="/api/practices/"+id+"/submit",key=prefix+"retry";String firstResult=mvc.perform(post(path).cookie(first).with(csrf()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String grading=db.queryForObject("SELECT grading_status FROM rs_practice_item WHERE id=?",String.class,item),stored=db.queryForObject("SELECT result_json::text FROM rs_practice_item WHERE id=?",String.class,item);String secondResult=mvc.perform(post(path).cookie(first).with(csrf()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertEquals(json.readTree(firstResult),json.readTree(secondResult));assertEquals(grading,db.queryForObject("SELECT grading_status FROM rs_practice_item WHERE id=?",String.class,item));assertEquals(json.readTree(stored),json.readTree(db.queryForObject("SELECT result_json::text FROM rs_practice_item WHERE id=?",String.class,item)));}
 long user(String name,BCryptPasswordEncoder encoder){return db.queryForObject("INSERT INTO rs_user(username,password_hash,role) VALUES (?,?,'STUDENT') RETURNING id",Long.class,name,encoder.encode(password));}
 Cookie login(String name)throws Exception{return mvc.perform(post("/api/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("username",name,"password",password)))).andExpect(status().isOk()).andReturn().getResponse().getCookie("RSID");}
 long knowledge(String code,String name,int order){return db.queryForObject("INSERT INTO rs_knowledge_point(subject_id,chapter_id,code,name,sort_order) VALUES (1,?,?,?,?) RETURNING id",Long.class,chapter,code,name,order);}
 long question(String type,String suffix,Object content,Object answer,Object rubric,double max){return question(kp,type,suffix,content,answer,rubric,max);}
 long question(long knowledgeId,String type,String suffix,Object content,Object answer,Object rubric,double max){long q=db.queryForObject("INSERT INTO rs_question(subject_id,question_no,origin,status) VALUES (1,?,'MANUAL','ACTIVE') RETURNING id",Long.class,(prefix+suffix).substring(0,Math.min(24,(prefix+suffix).length())));long v=db.queryForObject("INSERT INTO rs_question_version(question_id,version,subject_id,knowledge_point_id,type,max_score,content_json,answer_json,rubric_json,source_ref) VALUES (?,1,1,?,?,?,CAST(? AS jsonb),CAST(? AS jsonb),CAST(? AS jsonb),?) RETURNING id",Long.class,q,knowledgeId,type,max,json.valueToTree(content).toString(),json.valueToTree(answer).toString(),rubric==null?null:json.valueToTree(rubric).toString(),prefix+suffix);db.update("UPDATE rs_question SET current_version_id=? WHERE id=?",v,q);return q;}
 Map<String,Object> choiceContent(String stem){return Map.of("stem",stem,"options",List.of(Map.of("key","A","text","one"),Map.of("key","B","text","two"),Map.of("key","C","text","three")),"explanation","choice explanation");}
 Map<String,Object> rubric(double score){return Map.of("items",List.of(Map.of("criterion","complete", "score",score)));}
 JsonNode create(Cookie cookie,String key,List<Long> ids,int count)throws Exception{return json.readTree(mvc.perform(post("/api/practices").cookie(cookie).with(csrf()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("knowledgeIds",ids.stream().map(String::valueOf).toList(),"questionCount",count)))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}
 void start(Cookie cookie,long id)throws Exception{mvc.perform(post("/api/practices/"+id+"/start").cookie(cookie).with(csrf())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("IN_PROGRESS"));}
 byte[] png(){return Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");}
 int countResult(JsonNode result,String status,String field,boolean value){int n=0;for(JsonNode item:result.get("items"))if(item.at("/result/grading_status").asText().equals(status)&&item.at("/result/"+field).asBoolean()==value)n++;return n;}
 int countStatus(JsonNode result,String status){int n=0;for(JsonNode item:result.get("items"))if(item.at("/result/grading_status").asText().equals(status))n++;return n;}
 void assertNoSecrets(JsonNode node){if(node.isObject()){node.fieldNames().forEachRemaining(name->{assertFalse(Set.of("answer","correctAnswer","rubric","explanation","sourceRef","referenceAnswer","correctOption").contains(name),name+" leaked");assertNoSecrets(node.get(name));});}else if(node.isArray())node.forEach(this::assertNoSecrets);}
}
